const TEAMS_ALL=[...TEAMS,"PMO","Architecture","Finance"].filter((v,i,a)=>a.indexOf(v)===i);
const PRC={PR1:"--p4",PR2:"--s3",PR3:"--e4",PR4:"--u3",BAU:"--faint"};
const wkOf=iso=>clamp(Math.floor((wdOf(iso)-WK0)/5),0,NW-1);
const members=t=>st.people.filter(p=>p.team===t);
const cellTot=(id,w)=>allocTot(id,w);
const capOf=(id,w)=>100*(1-leaveFrac(id,w));
function peakTeam(){let best=null;TEAMS.forEach(t=>{const m=members(t);for(let w=0;w<NW;w++){const cap=m.reduce((a,p)=>a+capOf(p.id,w)*p.fte,0),use=m.reduce((a,p)=>a+cellTot(p.id,w)*p.fte+itemsOf(p.id,w).reduce((x,i)=>x+i.h/40*100,0),0);const u=cap?use/cap*100:0;if(!best||u>best.u)best={t,w,u}}});return best}
function overCells(team){let n=0;members(team).forEach(p=>{for(let w=0;w<NW;w++)if(cellTot(p.id,w)>capOf(p.id,w)+.5)n++});return n}
function allocCell(p,w){const a=st.alloc[p.id][w]||{},tot=cellTot(p.id,w),cap=capOf(p.id,w),lf=leaveFrac(p.id,w),over=tot>cap+.5;
 return `<div class="ppl-ac ${over?"over":""} ${lf>0?"lv":""}" data-ppl-cell="${p.id}:${w}" aria-label="${esc(p.n)}, week of ${WL[w]}, ${tot}% allocated of ${Math.round(cap)}% available">${Object.entries(a).filter(([k,v])=>v>0).map(([k,v])=>k==="BAU"?`<span class="ppl-chip lock" style="--cc:var(${PRC[k]})" title="Business as usual">BAU ${v}</span>`:`<button type="button" class="ppl-chip" data-ppl-chip="${p.id}:${w}:${k}" style="--cc:var(${PRC[k]||"--p4"})">${k} ${v}</button>`).join("")}<b class="ppl-tot ${over?"bad":tot>cap*.85?"warn":""}">${tot}%${lf>0?` <small>${Math.round(lf*5)}d off</small>`:""}</b></div>`}
function gridPane(){const m=members(st.capTeam),pk=peakTeam();
 const chips=`<div class="row">${TEAMS_ALL.map(t=>`<button class="chip" data-ppl-team="${esc(t)}" aria-pressed="${t===st.capTeam}">${esc(t)}${overCells(t)?` <span class="pill bad">${overCells(t)}</span>`:""}</button>`).join("")}</div>`;
 const foot=WL.map((_,w)=>{const cap=m.reduce((a,p)=>a+capOf(p.id,w)*p.fte,0),use=m.reduce((a,p)=>a+cellTot(p.id,w)*p.fte,0),u=cap?use/cap*100:0;return `<span class="ppl-ha ${uCls(u)}">${Math.round(u)}%</span>`}).join("");
 return card("Allocation grid",`Drag a project chip to another project bar (retags the hours), or to another week or person (moves them). Cells over capacity turn red. ${esc(st.capTeam)} has ${overCells(st.capTeam)} over-allocated person-weeks.`,`${chips}<div class="ppl-zones" id="pplZones" role="group" aria-label="Drop zones: projects">${PROJ.map(p=>`<span class="ppl-zone" data-ppl-zone="${p.id}" style="--cc:var(${PRC[p.id]})"><b>${p.id}</b> ${esc(p.short)}</span>`).join("")}</div>
 <div class="ppl-heatwrap"><div class="ppl-ag"><div class="ppl-ar ppl-hh"><span></span>${WL.map(w=>`<b>${w}</b>`).join("")}</div>${m.map(p=>`<div class="ppl-ar"><button class="ppl-hn" data-ppl-open="${p.id}"><i class="av" style="background:${col(p.c)}">${ini(p.n)}</i><span>${esc(p.n)}<small class="muted">${esc(p.role)}</small></span></button>${WL.map((_,w)=>allocCell(p,w)).join("")}</div>`).join("")}<div class="ppl-ar ppl-af"><span><b>Team load</b><small class="muted"> FTE-weighted</small></span>${foot}</div></div></div>
 <div class="row" style="margin-top:12px"><button class="btn primary" data-ppl-level="1">${ico("sparkle")} Level ${esc(st.capTeam)}</button>${aiChip({model:"Resource Agent",conf:.82,title:"Leveling proposal",src:["Allocation grid","Approved leave","Skills matrix"],guards:["Proposes moves, you approve","Never moves a milestone date","Does not change leave"]})}<span class="muted small">Formula: allocation % ÷ (100% − leave share). Business as usual cannot be moved.</span></div>`,`${fchip("m_wload")}${fchip("m_util")}`)}
function levelSim(team){const A=JSON.parse(JSON.stringify(st.alloc)),mv=[],un=[];const m=members(team);
 const tot=(id,w)=>Object.values(A[id][w]).reduce((a,b)=>a+b,0);
 for(let w=0;w<NW;w++){m.forEach(p=>{let guard=0;while(tot(p.id,w)>capOf(p.id,w)+.5&&guard++<6){const ks=Object.entries(A[p.id][w]).filter(([k,v])=>k!=="BAU"&&v>0).sort((a,b)=>a[1]-b[1]);if(!ks.length)break;const [k,v]=ks[0];
   const to=m.filter(q=>q.id!==p.id&&tot(q.id,w)+v<=capOf(q.id,w)).sort((a,b)=>tot(a.id,w)-tot(b.id,w))[0];
   if(to){A[p.id][w][k]-=v;if(!A[p.id][w][k])delete A[p.id][w][k];A[to.id][w][k]=(A[to.id][w][k]||0)+v;mv.push({from:p.id,to:to.id,w,k,v})}else{un.push({p:p.id,w});break}}})}
 return {mv,un}}
function levelDrawer(){const {mv,un}=levelSim(st.capTeam);const before=overCells(st.capTeam);
 openDrawer(`<div class="eyebrow">Resource Agent proposal</div><h3>Level ${esc(st.capTeam)}</h3><p class="muted" data-role="story">${mv.length?`${mv.length} moves clear ${before-new Set(un.map(u=>u.p+u.w)).size} of ${before} over-allocated person-weeks without touching a milestone.`:before?"No teammate has room in those weeks, so moves alone cannot fix it.":"Nothing is over capacity."}${un.length?` ${new Set(un.map(u=>u.p+":"+u.w)).size} person-weeks still need a bigger decision: move a date, add vendor staff or defer demand.`:""}</p>
 <div class="needs">${mv.slice(0,12).map(x=>`<div class="need" style="grid-template-columns:auto 1fr"><span class="pill ${"info"}">${x.k} ${x.v}%</span><div><b>${esc(nameOf(x.from))} → ${esc(nameOf(x.to))}</b><span class="muted small">Week of ${WL[x.w]}</span></div></div>`).join("")||empty("No moves","")}${mv.length>12?`<span class="muted small">and ${mv.length-12} more</span>`:""}</div>
 <div class="row" style="margin-top:14px"><button class="btn primary" data-ppl-applylevel="1" ${mv.length?"":"disabled"}>Apply ${mv.length} moves</button><button class="btn" data-ppl-x>Not now</button>${aiChip({model:"Resource Agent",conf:.82,title:"How it leveled",src:["Allocation grid","Approved leave"],guards:["Never moves a milestone date","Each move is audited"]})}</div>`)}
function applyLevel(){const {mv}=levelSim(st.capTeam);mv.forEach(x=>{const a=st.alloc[x.from][x.w];a[x.k]-=x.v;if(!a[x.k])delete a[x.k];const b=st.alloc[x.to][x.w];b[x.k]=(b[x.k]||0)+x.v});audit("leveled team",st.capTeam+": "+mv.length+" moves");toast("Applied "+mv.length+" moves to "+st.capTeam,"good");closeDrawer();render()}
