function leaveImpact(l){const p=H(l.who),w=wkOf(l.from),t=p.team,before=teamUtil(t,w);const was=l.st;l.st="approved";const after=teamUtil(t,w);l.st=was;return {w,t,before,after}}
function availPane(){const m=st.people.filter(p=>p.team===st.capTeam);const cal=`<div class="ppl-heatwrap"><div class="ppl-ag"><div class="ppl-ar ppl-hh"><span></span>${WL.map(w=>`<b>${w}</b>`).join("")}</div>${m.map(p=>`<div class="ppl-ar"><button class="ppl-hn" data-ppl-open="${p.id}"><i class="av" style="background:${col(p.c)}">${ini(p.n)}</i>${esc(p.n)}</button>${WL.map((_,w)=>{const a=WK0+5*w;const ls=st.leave.filter(l=>l.who===p.id&&l.st!=="declined"&&wdOf(l.to)>=a&&wdOf(l.from)<=a+4);return `<span class="ppl-lc">${ls.map(l=>`<span class="ppl-lbar ${l.st}" title="${esc(l.type)} ${dFmt(l.from)} to ${dFmt(l.to)} (${l.st})">${l.st==="pending"?"? ":""}${esc(l.type)}</span>`).join("")}</span>`}).join("")}</div>`).join("")}</div></div>`;
 const pend=st.leave.filter(l=>l.st==="pending"),rest=st.leave.filter(l=>l.st!=="pending");
 const row=l=>{const p=H(l.who),im=l.st==="pending"?leaveImpact(l):null;return `<div class="need" style="grid-template-columns:auto 1fr auto"><span class="pill ${l.st==="approved"?"good":l.st==="pending"?"warn":"mute"}">${l.st}</span><div><b>${esc(p.n)} · ${esc(l.type)} · ${dFmt(l.from)} to ${dFmt(l.to)}</b><span class="muted small" data-role="story">${esc(l.note||"No note")}${im?` Approving takes ${esc(im.t)} from <b>${Math.round(im.before)}%</b> to <b style="color:var(--${im.after>100?"bad":"good"})">${Math.round(im.after)}%</b> in the week of ${WL[im.w]}.`:""}</span></div>${l.st==="pending"?`<div class="act"><button class="btn primary" data-ppl-lv="${l.id}:approved">Approve</button><button class="btn" data-ppl-lv="${l.id}:declined">Decline</button></div>`:""}</div>`};
 return `${card("Availability calendar",`Leave and holidays for ${esc(st.capTeam)} over the next 8 weeks. Pending requests are hatched.`,`<div class="row" style="margin-bottom:10px">${TEAMS_ALL.map(t=>`<button class="chip" data-ppl-team="${esc(t)}" aria-pressed="${t===st.capTeam}">${esc(t)}</button>`).join("")}</div>${cal}`,`<button class="btn primary" data-ppl-leave="">Request leave</button>`)}${card("Leave requests",pend.length+" waiting for a decision. The impact line is computed from the allocation grid before you approve.",`<div class="needs">${pend.map(row).join("")}${rest.map(row).join("")}</div>`)}`}
function leaveForm(who){openForm({id:"ppl_leave",title:"Request leave",story:"Creates a pending request for the manager. It shows the effect on the team's load that week before anyone approves, and asks for a cover person if the team would go over capacity.",submit:"Submit request",
 fields:[{k:"who",label:"Who",type:"select",req:true,opts:st.people.filter(p=>p.kind==="human").map(p=>[p.id,p.n]),ph:"Pick a person"},{k:"type",label:"Type",type:"chips",req:true,opts:["Vacation","Sick day","Training","Parental"]},{k:"from",label:"From",type:"date",req:true},{k:"to",label:"To",type:"date",req:true},{k:"cover",label:"Cover person",type:"select",opts:st.people.map(p=>[p.id,p.n]),ph:"Optional",ai:{label:"Suggest",fn:v=>{const p=H(v.who);if(!p||!v.from)return null;const w=wkOf(v.from);const c=members(p.team).filter(q=>q.id!==p.id).map(q=>({q,u:util(q,w)})).filter(x=>x.u!=null).sort((a,b)=>a.u-b.u)[0];return c?c.q.id:null}}},{k:"note",label:"Note",type:"text",ph:"Optional"}],
 defaults:{who:who||"",type:"Vacation"},live:v=>{const el=document.getElementById("pplLvLive"),p=H(v.who);if(!el||!p||!v.from||!v.to)return;const l={who:v.who,from:v.from,to:v.to,st:"pending"};const im=leaveImpact(l);el.innerHTML=`<div class="ppl-eff small">${esc(p.team)} in the week of ${WL[im.w]}: ${Math.round(im.before)}% now, <b style="color:var(--${im.after>100?"bad":"good"})">${Math.round(im.after)}%</b> if approved. ${im.after>100?"The team would be over capacity, so a cover person is recommended.":"Within capacity."}</div>`},extra:'<div id="pplLvLive" style="flex-basis:100%"></div>',
 onSubmit:v=>{if(dTs(v.to)<dTs(v.from)){toast("The end date is before the start date","bad");return {close:false,toast:"Check the dates"}}st.leave.push({id:"LV"+(st.leave.length+1),who:v.who,from:v.from,to:v.to,type:v.type,st:"pending",note:(v.note||"")+(v.cover?" Cover: "+nameOf(v.cover)+".":"")});return {toast:"Request sent to "+nameOf((H(v.who)||{}).mgr),audit:nameOf(v.who)}}})}
/* find a person */
const FP_W={s:.45,a:.30,c:.15,k:.10};
function findRank(q){const w0=wkOf(q.from),w1=wkOf(q.to);const need=q.fte;const res=[];
 st.people.filter(p=>p.kind==="human"&&!["cd","oh","mr"].includes(p.id)&&(q.vend||p.type!=="vendor")).forEach(p=>{const lv=p.sk[q.skill]||0;if(lv<q.min)return;let free=0,n=0;for(let w=w0;w<=w1;w++){const u=util(p,w);free+=u==null?0:Math.max(0,100-u);n++}free/=n;const sk=lv/3,av=Math.min(1,free/need),ct=(q.pr&&[...Array(NW)].some((_,w)=>(st.alloc[p.id][w][q.pr]||0)>0))?1:0,ck=p.type==="vendor"?.6:1;
  const sc=100*(FP_W.s*sk+FP_W.a*av+FP_W.c*ct+FP_W.k*ck);res.push({p,lv,free,sk,av,ct,ck,sc})});
 return res.sort((a,b)=>b.sc-a.sc).slice(0,6)}
const FP0={skill:"si",min:2,from:"2026-10-19",to:"2026-11-13",fte:50,pr:"PR2",vend:true};
function findPane(){const q=st.find||FP0;const r=findRank(q);
 return `${card("Find me a person",`Who has ${esc(SK[q.skill])} at level ${q.min}+ and about ${q.fte}% free from ${dFmt(q.from)} to ${dFmt(q.to)}? Ranked below with the arithmetic shown.`,`<div class="formula">Score = 100 × (${FP_W.s} × Skill fit + ${FP_W.a} × Availability + ${FP_W.c} × Continuity on ${q.pr||"the project"} + ${FP_W.k} × Cost). Skill fit = level ÷ 3. Availability = free hours ÷ hours asked for, capped at 1. Continuity = 1 if already allocated to the project. Cost = 1 for employees, 0.6 for vendor staff.</div>
 <div class="needs" style="margin-top:14px">${r.map((x,i)=>`<div class="need ppl-cand" style="grid-template-columns:auto 1fr auto"><span class="num ppl-rank">${i+1}</span><div><b>${esc(x.p.n)} <span class="muted small">${esc(x.p.role)}${x.p.type==="vendor"?" · vendor":""}</span></b><div class="ppl-sb">${[["Skill",x.sk],["Free",x.av],["On project",x.ct],["Cost",x.ck]].map(([l,v])=>`<span><i style="width:${Math.round(v*100)}%"></i><em>${l} ${Math.round(v*100)}</em></span>`).join("")}</div><span class="muted small" data-role="story">Level ${x.lv} in ${esc(SK[q.skill])}, about ${Math.round(x.free)}% free on average${x.ct?", already on "+q.pr:""}.</span></div><div class="act"><span class="pill metric" data-role="metric">${Math.round(x.sc)}</span><button class="btn primary" data-ppl-alloc="${x.p.id}">Allocate ${q.fte}%</button></div></div>`).join("")||empty("No one meets that skill level","Lower the minimum level or include vendor staff.")}</div><div class="row" style="margin-top:12px">${aiChip({model:"Resource Agent",conf:.8,title:"How candidates were ranked",src:["Skills matrix","Allocation grid","Approved leave","Vendor rate card"],guards:["Ranks only. A manager allocates.","No pay or performance data used"]})}<button class="btn primary" data-ppl-find="1">Change the request</button></div>`,fchip("m_util"))}`}
