function seedStatus(p,c){const r=hash(p.id+c.id);if(daysTo(c.due)<=0){if(r<c.rate){const d=addD(c.due,-Math.floor(hash(p.id+c.id+"d")*28)-1);return {st:"done",due:c.due,done:d,score:Math.round(78+hash(p.id+c.id+"s")*21),exp:c.recur?addM(d,c.recur):null}}return r<c.rate+.07?{st:"progress",due:c.due,pct:Math.round(20+hash(p.id+"p")*60)}:{st:"todo",due:c.due,pct:0}}
 if(r<c.rate*.6){const d=addD(TODAY_ISO,-Math.floor(hash(p.id+c.id+"d")*20)-1);return {st:"done",due:c.due,done:d,score:Math.round(80+hash(p.id+c.id+"s")*19),exp:c.recur?addM(d,c.recur):null}}return r<.62?{st:"progress",due:c.due,pct:Math.round(20+hash(p.id+"p")*60)}:{st:"todo",due:c.due,pct:0}}
function ensureEnr(pid,fresh){const p=H(pid);if(!p)return;const E=st.enr[pid]=st.enr[pid]||{};st.courses.forEach(c=>{if(!E[c.id]&&inAud(c,p)){const e=fresh?{st:"todo",due:LP1(c.id)?addD(p.start||"2026-10-12",5):c.due,pct:0}:seedStatus(p,c);if(c.cert&&e.st!=="done"){const pd=hash(p.id+c.id+"cx")<.12?addD("2025-09-10",Math.floor(hash(p.id+"q")*20)):addD("2025-10-20",Math.floor(hash(p.id+c.id+"x")*60));e.prev=pd;e.exp=addM(pd,12)}E[c.id]=e}})}
